782|# -Status and -Wait refuse a query with exit 4 - never mistaken for a run's result (D7).
783|function Stop-StatusQuery {
784|    param([string]$Message)
785|    Write-Host "codex-consult: $Message" -ForegroundColor Red
786|    exit 4
787|}
